ALPHA2 = ['a000001600000000', '9000000a00000000', '5000000e00800004', '5000000a00000000', '0000002200000000', 'a000001600000001', '8000000a00000000', '5000000e00000000', '5000004a00000000', '0000402600000000', '2000001600000001', '8000000a00000000', '5000000e00800000', '4000004a00000000', '0000402600000000', 'a000001600000001', '8000001a00000000', '5000000e00000004', '5000004a00000000', '0000002600000000', 'a000001600000001', 'c000000a00000000', '5000000e00000000', '5000004a00000000', '0000002600000000']
CHUNK, G = 7316, 3520259
INDEX = 122745632515
RC = [0x1, 0x8082, 0x800000000000808A, 0x8000000080008000, 0x808B]
RHO = [0, 1, 62, 28, 27, 36, 44, 6, 55, 20, 3, 10, 43, 25, 39, 41, 45, 15, 21, 8, 18, 2, 61, 56, 14]
M = (1 << 64) - 1


def lanes(hexes):
    return [int(h, 16) for h in hexes]


def element(chunk, g):
    x = lanes(X0)
    gray = g ^ (g >> 1)
    for j in range(24):
        if (gray >> j) & 1:
            x = [a ^ b for a, b in zip(x, lanes(BASIS[j]))]
    for j in range(14):
        if (chunk >> j) & 1:
            x = [a ^ b for a, b in zip(x, lanes(BASIS[24 + j]))]
    return x


def rot(v, n):
    return ((v << n) | (v >> (64 - n))) & M if n else v


def rounds(a, n):
    a = list(a)
    for r in range(n):
        c = [a[x] ^ a[x + 5] ^ a[x + 10] ^ a[x + 15] ^ a[x + 20] for x in range(5)]
        d = [c[(x - 1) % 5] ^ rot(c[(x + 1) % 5], 1) for x in range(5)]
        b = [0] * 25
        for y in range(5):
            for x in range(5):
                b[y + 5 * ((2 * x + 3 * y) % 5)] = rot(a[x + 5 * y] ^ d[x], RHO[x + 5 * y])
        a = [b[x + 5 * y] ^ (~b[(x + 1) % 5 + 5 * y] & b[(x + 2) % 5 + 5 * y]) & M for y in range(5) for x in range(5)]
        a[0] ^= RC[r]
    return a


def message(x):
    block = b"".join(v.to_bytes(8, "little") for v in x[:17])
    assert block[135] == 0x86 and all(v == 0 for v in x[17:])
    return block[:135]


def alpha2_ok(x):
    y = [a ^ b for a, b in zip(x, lanes(DELTA))]
    return [p ^ q for p, q in zip(rounds(x, 2), rounds(y, 2))] == lanes(ALPHA2)


def main():
    req = json.loads(sys.stdin.read())
    x = element(CHUNK, G)
    y = [a ^ b for a, b in zip(x, lanes(DELTA))]
    ma, mb = message(x).hex(), message(y).hex()
    hit = int(alpha2_ok(x))
    trials = []
    for t in req["trials"]:
        s = int(t["seed"], 16)
        rx = element((s >> 24) & ((1 << 14) - 1), s & ((1 << 24) - 1))
        trials.append({"trial": t["trial"], "message_a_hex": ma, "message_b_hex": mb,
                       "observations": {"index_log2_times_1000": 36837, "pair_alpha2_ok": hit,
                                         "seeded_element_alpha2_ok": int(alpha2_ok(rx))}})
    sys.stdout.write(json.dumps({"schema_version": 1, "trials": trials}))


main()
